+
+async function rebuildReadModels() {
+  const client = await pool.connect();
+  try {
+    await client.query("BEGIN");
+
+    const result = await client.query("SELECT COUNT(*) AS total FROM event_stream WHERE processed = false");
+    const totalEvents = parseInt(result.rows[0].total, 10);
+    console.log(`[Rebuild] Processing ${totalEvents} unprocessed events...`);
+
+    const { dispatchToProjections } = require("./projections");
+
+    for (let i = 0; i < totalEvents; i += BATCH_SIZE) {
+      const rows = await client.query(
+        `SELECT event_id, payload FROM event_stream WHERE processed = false ORDER BY occurred_at ASC, version ASC LIMIT $1 OFFSET $2`,
+        [BATCH_SIZE, i]
+      );
+
+      for (const row of rows.rows) {
+        try {
+          const event = fromPayload(row.payload);
+          await dispatchToProjections(client, event);
+        } catch (err) {
+          console.error(`[Rebuild] Error dispatching event ${row.event_id}:`, err.message);
+        }
+      }
+
+      const eventIds = rows.rows.map((r) => r.event_id);
+      if (eventIds.length > 0) {
+        await client.query(
+          "UPDATE event_stream SET processed = true, processed_at = NOW() WHERE event_id = ANY($1::uuid[])",
+          [eventIds]
+        );
+      }
+
+      console.log(`[Rebuild] Processed ${Math.min(i + BATCH_SIZE, totalEvents)}/${totalEvents} events`);
+    }
+
+    await client.query("COMMIT");
+    console.log("[Rebuild] Read models rebuilt successfully");
+  } catch (err) {
+    await client.query("ROLLBACK");
+    throw err;
+  } finally {
+    client.release();
+  }
+}
+
+async function verifyMigration(expectedUniqueTxCount, expectedDonationCount) {
+  const uniqueTxResult = await pool.query(
+    `SELECT COUNT(DISTINCT (payload->'data'->>'transactionHash')) AS count
+     FROM event_stream
+     WHERE event_type IN ('DonationRecorded', 'MigratedDonation') AND payload->'data'->>'isMatch' = 'false'`
+  );
+  const actualUniqueTxCount = parseInt(uniqueTxResult.rows[0]?.count || "0", 10);
+
+  const donationResult = await pool.query(
+    `SELECT SUM((payload->'data'->>'amountXlm')::numeric) AS total
+     FROM event_stream
+     WHERE event_type IN ('DonationRecorded', 'MigratedDonation') AND payload->'data'->>'isMatch' = 'false'`
+  );
+  const eventTotalXlm = parseFloat(donationResult.rows[0]?.total?.toString() || "0");
+
+  const legacyTotalResult = await pool.query("SELECT SUM(amount_xlm::numeric) AS total FROM donations WHERE currency = 'XLM'");
+  const legacyTotalXlm = parseFloat(legacyTotalResult.rows[0]?.total?.toString() || "0");
+
+  const donorEventsResult = await pool.query(
+    "SELECT COUNT(DISTINCT (payload->'data'->>'donorAddress')) AS count FROM event_stream WHERE aggregate_type IN ('Donation', 'MigratedDonation')"
+  );
+  const eventUniqueDonors = parseInt(donorEventsResult.rows[0]?.count || "0", 10);
+
+  const legacyUniqueDonorsResult = await pool.query(
+    "SELECT COUNT(DISTINCT donor_address) AS count FROM donations"
+  );
+  const legacyUniqueDonors = parseInt(legacyUniqueDonorsResult.rows[0]?.count || "0", 10);
+
+  const matchInEventsResult = await pool.query(
+    "SELECT COUNT(*) AS count FROM event_stream WHERE event_type = 'MigratedDonation' AND payload->'data'->>'isMatch' = 'true'"
+  );
+  const eventMatchCount = parseInt(matchInEventsResult.rows[0]?.count || "0", 10);
+
+  const legacyMatchResult = await pool.query(
+    "SELECT SUM(matched_xlm::numeric) AS total FROM donation_matches"
+  );
+  const legacyMatchTotal = parseFloat(legacyMatchResult.rows[0]?.total?.toString() || "0");
+
+  return {
+    uniqueTxHashesMatch: actualUniqueTxCount === expectedUniqueTxCount,
+    expectedUniqueTxCount,
+    actualUniqueTxCount,
+    xlmTotalMatch: Math.abs(eventTotalXlm - legacyTotalXlm) < 0.0000001,
+    eventTotalXlm,
+    legacyTotalXlm,
+    uniqueDonorsMatch: eventUniqueDonors === legacyUniqueDonors,
+    eventUniqueDonors,
+    legacyUniqueDonors,
+    eventMatchCount,
+    legacyMatchTotal,
+  };
+}
+
+module.exports = { runLegacyMigration, rebuildReadModels, verifyMigration };
diff --git a/backend/src/eventSourcing/projections.js b/backend/src/eventSourcing/projections.js
new file mode 100644
index 0000000..07a676d
--- /dev/null
+++ b/backend/src/eventSourcing/projections.js
@@ -0,0 +1,235 @@
+"use strict";
+
+const { v4: uuid } = require("uuid");
+const { round7 } = require("./aggregates");
+
+const PROJECTION_BATCH_SIZE = 500;
+
+const registry = new Map();
+
+class Projection {
+  subscribe(eventType) {
+    if (!registry.has(eventType)) registry.set(eventType, []);
+    registry.get(eventType).push(this);
+  }
+
+  getSubscribers(eventType) {
+    return registry.get(eventType) || [];
+  }
+}
+
+const projectProjection = new Projection();
+const donorProjection  = new Projection();
+const matchProjection  = new Projection();
+const jobProjection    = new Projection();
+const milestoneProjection = new Projection();
+
+projectProjection.subscribe("DonationRecorded");
+projectProjection.subscribe("MatchApplied");
+projectProjection.subscribe("MigratedDonation");
+
+donorProjection.subscribe("DonationRecorded");
+donorProjection.subscribe("MatchApplied");
+donorProjection.subscribe("MigratedDonation");
+
+matchProjection.subscribe("MatchApplied");
+matchProjection.subscribe("MatchCreated");
+matchProjection.subscribe("MigratedDonation");
+
+jobProjection.subscribe("JobReleased");
+
+milestoneProjection.subscribe("MilestoneReached");
+
+function getAllProjections() {
+  return [projectProjection, donorProjection, matchProjection, jobProjection, milestoneProjection];
+}
+
+async function dispatchToProjections(client, event) {
+  const subscribers = registry.get(event.eventType) || [];
+  for (const projection of subscribers) {
+    await projection.apply(client, event);
+  }
+}
+
+async function applyProjectProjection(client, event) {
+  const data = event.data;
+
+  if (event.eventType === "MatchApplied") {
+    await client.query(
+      `UPDATE projects
+       SET raised_xlm = raised_xlm + $1::numeric,
+           donor_count = donor_count + 1,
+           updated_at = NOW(),
+           projection_cursor = GREATEST(projection_cursor, $2)
+       WHERE id = $3`,
+      [data.matchAmount.toFixed(7), event.version, data.projectId]
+    );
+  } else if (event.eventType === "DonationRecorded") {
+    const xlmDonation = data.currency === "XLM" ? data.amountXlm : 0;
+    await client.query(
+      `UPDATE projects
+       SET raised_xlm = raised_xlm + $1::numeric,
+           updated_at = NOW(),
+           projection_cursor = GREATEST(projection_cursor, $2)
+       WHERE id = $3`,
+      [xlmDonation.toFixed(7), event.version, data.projectId]
+    );
+  } else if (event.eventType === "MigratedDonation") {
+    const amt = data.isMatch ? data.amountXlm : data.amountXlm;
+    await client.query(
+      `UPDATE projects
+       SET raised_xlm = raised_xlm + $1::numeric,
+           updated_at = NOW(),
+           projection_cursor = GREATEST(projection_cursor, $2)
+       WHERE id = $3`,
+      [amt.toFixed(7), event.version, data.projectId]
+    );
+  }
+}
+
+projectProjection.apply = async (client, event) => {
+  await applyProjectProjection(client, event);
+};
+
+function computeBadges(totalXLM) {
+  const BADGE_THRESHOLDS = [
+    { tier: "earth", min: 2000 },
+    { tier: "forest", min: 500 },
+    { tier: "tree", min: 100 },
+    { tier: "seedling", min: 10 },
+  ];
+  const earned = [];
+  for (const badge of BADGE_THRESHOLDS) {
+    if (totalXLM >= badge.min) {
+      earned.push({ tier: badge.tier, earnedAt: new Date().toISOString() });
+      break;
+    }
+  }
+  return earned;
+}
+
+async function getExistingDonorTotal(client, donorAddress) {
+  const result = await client.query(
+    "SELECT total_donated_xlm FROM donor_stats WHERE public_key = $1",
+    [donorAddress]
+  );
+  if (result.rows[0]) {
+    return parseFloat(result.rows[0].total_donated_xlm?.toString() || "0");
+  }
+  return 0;
+}
+
+async function upsertDonorStats(client, donorAddress, xlmDelta, version) {
+  const existingTotal = await getExistingDonorTotal(client, donorAddress);
+  const newTotal = round7(existingTotal + xlmDelta);
+  const badges = computeBadges(newTotal);
+
+  await client.query(
+    `INSERT INTO donor_stats (public_key, total_donated_xlm, projects_supported, badges, projection_cursor)
+     VALUES ($1, $2::numeric, 0, $3::jsonb, $4)
+     ON CONFLICT (public_key) DO UPDATE SET
+       total_donated_xlm = EXCLUDED.total_donated_xlm,
+       badges = EXCLUDED.badges,
+       projection_cursor = EXCLUDED.projection_cursor`,
+    [donorAddress, newTotal.toFixed(7), JSON.stringify(badges), version]
+  );
+}
+
+async function syncDonorProjectCount(client, donorAddress, version) {
+  await client.query(
+    `UPDATE donor_stats
+     SET projects_supported = sub.proj_count,
+         projection_cursor = GREATEST(donor_stats.projection_cursor, $2)
+     FROM (
+       SELECT COUNT(DISTINCT (payload->'data'->>'projectId')) AS proj_count
+       FROM event_stream
+       WHERE aggregate_type IN ('Donation', 'MigratedDonation', 'MatchApplied')
+         AND payload->'data'->>'donorAddress' = $1
+     ) sub
+     WHERE donor_stats.public_key = $1`,
+    [donorAddress, version]
+  );
+}
+
+async function applyDonorProjection(client, event) {
+  const data = event.data;
+  let xlmDelta = 0;
+
+  if (event.eventType === "MigratedDonation") {
+    xlmDelta = data.isMatch ? data.amountXlm : (data.currency === "XLM" ? data.amountXlm : 0);
+  } else {
+    xlmDelta = data.currency === "XLM" ? data.amountXlm : 0;
+  }
+
+  await upsertDonorStats(client, data.donorAddress, xlmDelta, event.version);
+  await syncDonorProjectCount(client, data.donorAddress, event.version);
+}
+
+donorProjection.apply = async (client, event) => {
+  await applyDonorProjection(client, event);
+};
+
+async function applyMatchProjection(client, event) {
+  const data = event.data;
+  const matchId = data.matchId;
+
+  if (event.eventType === "MatchApplied") {
+    await client.query(
+      `UPDATE match_state
+       SET matched_xlm = matched_xlm + $1::numeric,
+           projection_cursor = GREATEST(projection_cursor, $2)
+       WHERE match_id = $3`,
+      [data.matchAmount.toFixed(7), event.version, matchId]
+    );
+  } else if (event.eventType === "MatchCreated" || event.eventType === "MigratedDonation" && data.isMatch === true) {
+    await client.query(
+      `INSERT INTO match_state (match_id, matched_xlm, cap_xlm, multiplier, projection_cursor)
+       VALUES ($1, '0'::numeric, $2, $3, $4)
+       ON CONFLICT (match_id) DO NOTHING`,
+      [matchId, data.capXlm?.toFixed(7) || "0", data.multiplier || 1, event.version]
+    );
+  }
+}
+
+matchProjection.apply = async (client, event) => {
+  await applyMatchProjection(client, event);
+};
+
+async function applyJobProjection(client, event) {
+  const jobId = event.aggregateId.split(":")[1];
+  await client.query(
+    `UPDATE jobs
+     SET status = 'completed',
+         release_transaction_hash = $1,
+         updated_at = NOW(),
+         projection_cursor = GREATEST(projection_cursor, $2)
+     WHERE id = $3`,
+    [event.data.releaseTransactionHash, event.version, jobId]
+  );
+}
+
+jobProjection.apply = async (client, event) => {
+  await applyJobProjection(client, event);
+};
+
+async function applyMilestoneProjection(client, event) {
+  const data = event.data;
+  await client.query(
+    `UPDATE project_milestones
+     SET reached_at = NOW(),
+         transaction_hash = $1,
+         projection_cursor = GREATEST(projection_cursor, $2)
+     WHERE id = $3 AND project_id = $4`,
+    [data.transactionHash, event.version, data.milestoneId, data.projectId]
+  );
+}
+
+milestoneProjection.apply = async (client, event) => {
+  await applyMilestoneProjection(client, event);
+};
+
+module.exports = {
+  Projection,
+  getAllProjections,
+  dispatchToProjections,
+};
